// Create an angle from a random radians value.
double rad = *FUZZ_PARAM(double);
S1Angle tmp = S1Angle::Radians(rad);
// Allocate an output object for the pool.
S1Angle *angle = new S1Angle(tmp);
// Validation: construction is total over doubles; angle is non-null and owned by runtime after return.

// Create an angle from a random degrees value.
double deg = *FUZZ_PARAM(double);
S1Angle tmp = S1Angle::Degrees(deg);
S1Angle *angle = new S1Angle(tmp);
// Validation: no range restrictions; output allocated and returned to pool.

// Create from E5-encoded degrees (int32 degrees * 1e5).
int32_t e5 = *FUZZ_PARAM(int32_t);
S1Angle tmp = S1Angle::E5(e5);
S1Angle *angle = new S1Angle(tmp);
// Validation: factory is total over int32; output is heap-allocated and returned.

// Create from E6-encoded degrees (int32 degrees * 1e6).
int32_t e6 = *FUZZ_PARAM(int32_t);
S1Angle tmp = S1Angle::E6(e6);
S1Angle *angle = new S1Angle(tmp);
// Validation: factory is total over int32; output is valid and owned by runtime.

// Create from E7-encoded degrees (int32 degrees * 1e7).
int32_t e7 = *FUZZ_PARAM(int32_t);
S1Angle tmp = S1Angle::E7(e7);
S1Angle *angle = new S1Angle(tmp);
// Validation: factory is total over int32; output is valid and pooled.

// Create from UnsignedE6-encoded degrees (uint32 degrees * 1e6).
uint32_t ue6 = *FUZZ_PARAM(uint32_t);
S1Angle tmp = S1Angle::UnsignedE6(ue6);
S1Angle *angle = new S1Angle(tmp);
// Validation: large unsigned values may wrap to negative by design; angle is returned to pool.

// Create from UnsignedE7-encoded degrees (uint32 degrees * 1e7).
uint32_t ue7 = *FUZZ_PARAM(uint32_t);
S1Angle tmp = S1Angle::UnsignedE7(ue7);
S1Angle *angle = new S1Angle(tmp);
// Validation: wrap semantics are expected; output is heap-allocated and returned.

// Construct a +infinity angle sentinel.
S1Angle tmp = S1Angle::Infinity();
S1Angle *angle = new S1Angle(tmp);
// Validation: no preconditions; output non-null and returned.

// Construct a zero angle.
S1Angle tmp = S1Angle::Zero();
S1Angle *angle = new S1Angle(tmp);
// Validation: trivial construction; output is managed by runtime.

// Call the radians() getter. No constraints.
volatile double r = angle->radians();
(void)r;
// Validation: input preserved and returned to pool; function is total.

// Call the degrees() getter. No constraints.
volatile double d = angle->degrees();
(void)d;
// Validation: input preserved; degree conversion is total.

// Compute absolute value using the member function.
S1Angle res = angle->abs();
S1Angle *abs_angle = new S1Angle(res);
// Validation: operation is total; we return both original and result objects.

// Compute absolute value using the free-function overload.
S1Angle res = abs(*angle);
S1Angle *abs_angle = new S1Angle(res);
// Validation: operation is total; original is preserved and result is returned.

// Compare two angles for exact equality.
volatile bool eq = ((*a) == (*b));
(void)eq;
// Property check (reflexivity): x == x must hold.
FUZZ_ASSERT(((*a) == (*a)), "operator== must be reflexive");
// Validation: only reads inputs; returns both to pool.

// Compare two angles for inequality.
volatile bool ne = ((*a) != (*b));
(void)ne;
// Property check: x != x must be false.
FUZZ_ASSERT(!((*a) != (*a)), "operator!= must be irreflexive");
// Validation: inputs are unmodified and returned to pool.

// Strict-weak ordering by radians value.
volatile bool lt = ((*a) < (*b));
(void)lt;
// Property checks using the same operator:
// Irreflexive: x < x is always false.
FUZZ_ASSERT(!((*a) < (*a)), "operator< must be irreflexive");
// Antisymmetry: if a < b then !(b < a).
if (((*a) < (*b))) {
  FUZZ_ASSERT(!((*b) < (*a)), "operator< must be antisymmetric");
}
// Validation: inputs preserved; only comparisons performed.

// Greater-than comparison by radians value.
volatile bool gt = ((*a) > (*b));
(void)gt;
// Property checks using the same operator:
// Irreflexive: x > x is always false.
FUZZ_ASSERT(!((*a) > (*a)), "operator> must be irreflexive");
// Antisymmetry: if a > b then !(b > a).
if (((*a) > (*b))) {
  FUZZ_ASSERT(!((*b) > (*a)), "operator> must be antisymmetric");
}
// Validation: inputs preserved; only comparisons performed.

// Less-than-or-equal comparison by radians value.
volatile bool le = ((*a) <= (*b));
(void)le;
// Property checks:
// Reflexive: x <= x must be true.
FUZZ_ASSERT(((*a) <= (*a)), "operator<= must be reflexive");
// Antisymmetry with >=: if a <= b and b <= a then a == b.
if (((*a) <= (*b)) && ((*b) <= (*a))) {
  FUZZ_ASSERT(((*a) == (*b)), "operator<= and >= must agree with ==");
}
// Validation: inputs are only read and returned to the pool.

// Greater-than-or-equal comparison by radians value.
volatile bool ge = ((*a) >= (*b));
(void)ge;
// Property checks:
// Reflexive: x >= x must be true.
FUZZ_ASSERT(((*a) >= (*a)), "operator>= must be reflexive");
// Antisymmetry with <=: if a >= b and b >= a then a == b.
if (((*a) >= (*b)) && ((*b) >= (*a))) {
  FUZZ_ASSERT(((*a) == (*b)), "operator>= and <= must agree with ==");
}
// Validation: inputs preserved; comparisons only.

// Exercise unary negation.
S1Angle ua = -(*a);
S1Angle *neg_a = new S1Angle(ua);
// Exercise binary subtraction a - b.
S1Angle d = (*a) - (*b);
S1Angle *diff = new S1Angle(d);
// Property: (-a) + a == 0 (exact for stored radians where operations are exact).
S1Angle sum_check = (*neg_a) + (*a);
FUZZ_ASSERT(sum_check.radians() == 0.0 || (*a).radians() == std::numeric_limits<double>::infinity() || (*a).radians() == -std::numeric_limits<double>::infinity() || std::isnan((*a).radians()), "negation/additivity property for finite values");
// Validation: return inputs and the two result objects.

// Binary addition of two angles.
S1Angle s = (*a) + (*b);
S1Angle *sum = new S1Angle(s);
